// LIFE-03 / TEN-12: the tenant export field lists, rendered from the single registry so the
// doc cannot drift from what toSnapshot actually writes (D187, D284).
// docs/ops/export-field-lists.md is generated by `npm run docs:fields` and drift-tested.
import {
  allTenantCollections,
  ORGANIZATION_EXPORT_FIELDS,
  type CollectionSpec,
} from "./registry";

const AUTH_NEVER =
  "Never exported (auth collection). Logins return through the disaster-recovery path, not the export (LIFE-03, TEN-12).";

const NEVER =
  "Never exported or restored: per-person, per-device or ephemeral rows (device keys, alert bodies, download keys; D187, P11).";

function section(name: string, spec: CollectionSpec | null): string[] {
  const out = [`## ${name}`, ""];
  if (spec && spec.kind === "auth") {
    out.push(AUTH_NEVER, "");
    return out;
  }
  if (spec && spec.export === "never") {
    out.push(NEVER, "");
    return out;
  }
  const fields = spec
    ? (spec.export as readonly string[])
    : ORGANIZATION_EXPORT_FIELDS;
  for (const f of fields) out.push(`- \`${f}\``);
  out.push("");
  if (spec) {
    out.push(`Restore mode: ${spec.restore ?? "replace"}.`);
    if (spec.rowFilter) {
      out.push(
        `Rows: only those with \`${spec.rowFilter.field}\` = \`${spec.rowFilter.equals}\` (others never leave the server).`,
      );
    }
    if (spec.public) {
      const gates = spec.publicWhen ?? {};
      const listed = spec.public
        .map((f) =>
          Object.hasOwn(gates, f)
            ? `\`${f}\` (only when \`${gates[f]}\` is on)`
            : `\`${f}\``,
        )
        .join(", ");
      out.push(`Public (visitor-readable) fields: ${listed}.`);
    }
    if (spec.ownerField) out.push(`Owner field: \`${spec.ownerField}\`.`);
  } else {
    out.push(
      "Restore mode: tenant root record (updated in place, never recreated).",
    );
  }
  out.push("");
  return out;
}

/** Deterministic markdown: sorted collections, fields in export order, LF endings. */
export function renderFieldLists(): string {
  const specs = new Map<string, CollectionSpec | null>(
    Object.entries(allTenantCollections()) as [string, CollectionSpec][],
  );
  specs.set("organizations", null);
  const names = [...specs.keys()].sort();
  const lines = [
    "# Tenant export field lists (generated)",
    "",
    "Generated from packages/db/src/registry.ts by `npm run docs:fields`. Do not edit by hand. Deny by default (D187, D284).",
    "",
    "Only the fields listed here are written to a tenant export, page version or add-on backup. Any other field, including every password, token, hash, API key and credential, is never written.",
    "",
  ];
  for (const name of names) lines.push(...section(name, specs.get(name)!));
  return lines.join("\n").replace(/\n+$/, "\n");
}
